EOF
cat > /tmp/termcheck/src/main.rs <<'EOF'
use clap::{Arg, ArgAction, Command};

fn cmd() -> Command {
    Command::new("fmt")
        .arg(
            Arg::new("tag")
                .long("tag")
                .visible_alias("label")
                .short('t')
                .num_args(1..=3)
                .value_parser(["red", "green", "blue"])
                .value_delimiter(',')
                .value_terminator(";"),
        )
        .arg(
            Arg::new("raw")
                .long("raw")
                .action(ArgAction::SetTrue)
                .conflicts_with("tag"),
        )
        .arg(Arg::new("path").value_parser(["src", "dst"]))
}

fn try_parse(args: &[&str]) {
    let mut c = cmd();
    let r = c.try_get_matches_from(std::iter::once("fmt").chain(args.iter().copied()));
    match r {
        Ok(m) => {
            let tags: Vec<String> = m.get_many::<String>("tag").map(|v| v.cloned().collect()).unwrap_or_default();
            let path: Option<&String> = m.get_one("path");
            println!("OK   {:?} -> tag={:?} path={:?} raw={}", args, tags, path, m.get_flag("raw"));
        }
        Err(e) => println!("ERR  {:?} -> {}", args, e.kind() as u8),
    }
}

fn main() {
    try_parse(&["--tag", "red", ";"]);
    try_parse(&["--tag", "red,green", ";"]);
    try_parse(&["--tag=red,green,blue", ";"]);
    try_parse(&["--tag", ";"]);
    try_parse(&["--tag", "red", ";", ";"]);
    try_parse(&["--tag", "red", ";", "src"]);
    try_parse(&["--tag", "red", ";", "--", ";"]);
    try_parse(&["--tag", "red", ";", "--", "src"]);
    try_parse(&["--tag=red,", ";"]);
    try_parse(&["--tag", "red,", ";"]);
    try_parse(&["--tag=red;", "x"]);
    try_parse(&["--tag", ";x"]);
    try_parse(&["--label", "red", ";"]);
    try_parse(&["-tred", ";"]);
    try_parse(&["--tag", "red", "green", ";"]);
    try_parse(&["--tag", "red", "green", "blue", ";"]);
    try_parse(&["--tag", "red", "green", "blue", "x", ";"]);
    try_parse(&["--tag=red,green"]);
    try_parse(&["--tag", "red", "purple", ";"]);
    try_parse(&["--tag", "red,red", ";"]);
    try_parse(&["--tag", "red", ";", "--raw"]);
}
EOF
