        }
        Err(e) => println!("ERR  {:?} {}", args, e.to_string().lines().next().unwrap()),
    }
}
fn main() {
    p(&["--term", "foo;bar", ";", "x"]);
    p(&["--term=foo;bar", ";"]);
    p(&["--term", "foo,bar", ";", "x"]);
    p(&["--term", ";"]);
}
