/// Whether `value` is the option's standalone [`Arg::value_terminator`].
///
/// The terminator only has meaning while the option is taking separate value
/// words; it is matched as a whole word, so a value that merely contains the
/// terminator (e.g. a delimiter segment like `a;b`) is never treated as one.
fn is_value_terminator(opt: &clap::Arg, value: &str) -> bool {
    opt.get_value_terminator()
        .is_some_and(|terminator| terminator.as_str() == value)
}

/// The ongoing option state when the current whole word is exactly that
/// option's value terminator.
fn as_value_terminator<'a, 's>(
    state: &'a ParseState<'a>,
    arg: &clap_lex::ParsedArg<'s>,
) -> Option<&'a OptState<'a>> {
    let ParseState::Opt(opt_state) = state else {
        return None;
    };
    let value = arg.to_value().ok()?;
    is_value_terminator(opt_state.opt, value).then_some(opt_state)
}

/// Apply the standalone terminator: value taking ends and ordinary parsing
/// resumes. Illegal positions (a dangling delimiter segment, a second
/// terminator) are flagged before this point.
fn terminate_opt_value(state: OptState<'_>) -> ParseState<'_> {
    debug_assert!(!state.open && !state.terminated);
    ParseState::ValueDone
}

