    // word, no matter whether the values arrived through `=`, a separate
    // word, a short flag or an alias. Keep a one-word "closed" window so
    // every spelling reaches the same explicit end state.
    Ok(Some(OptState {
        opt,
        word: ordinal + 1,
        used,
        open: false,
        closed: true,
    }))
} else {
    Ok(None)
