fn p(mut c: Command, args: &[&str]) {
    match c.try_get_matches_from(std::iter::once("do").chain(args.iter().copied())) {
        Ok(m) => {
            let v: Vec<String> = m.get_many::<String>("t").map(|x| x.cloned().collect()).unwrap_or_default();
            println!("OK   {:?} t={:?} o={:?}", args, v, m.get_one::<String>("o"));
