use clap::{Arg, ArgAction, Command};
use clap_complete::engine::complete;
use std::ffi::OsString;
use std::path::Path;

fn cmd() -> Command {
    Command::new("fmt")
        .arg(Arg::new("tag").long("tag").visible_alias("label").short('t')
            .num_args(1..=3).value_parser(["red","green","blue"])
            .value_delimiter(',').value_terminator(";"))
        .arg(Arg::new("raw").long("raw").action(ArgAction::SetTrue).conflicts_with("tag"))
        .arg(Arg::new("path").value_parser(["src","dst"]))
}
fn cv(words: &[&str], idx: usize, dir: Option<&Path>) -> String {
    let mut c = cmd();
    let mut args = vec![OsString::from("fmt")];
    args.extend(words.iter().map(|s| OsString::from(*s)));
    match complete(&mut c, args, idx, dir) {
        Ok(cs) => cs.iter().map(|c| c.get_value().to_string_lossy().to_string())
            .collect::<Vec<_>>().join(","),
        Err(e) => format!("ERR:{}", e),
    }
}
fn show(words: &[&str]) {
    // last word is the cursor word; idx counts binary name too
    println!("{:<40} => {}", words.join(" "), cv(words, words.len(), None));
}
#[test]
fn probe() {
    // dangling-comma closed word, next empty word
    show(&["--tag=red,",""]);
    show(&["--label=red,",""]);
    show(&["-tred,",""]);
    show(&["-t=red,",""]);
    show(&["--tag","red,",""]);
    // editing the current word filters last segment, keeps prefix
    show(&["--tag=red,g"]);
    show(&["--tag=red,gr"]);
    show(&["--tag=red,r"]);
    show(&["--label=red,b"]);
    show(&["-tred,b"]);
    show(&["-t=red,b"]);
    // separator-separate value words
    show(&["--tag","red","green,",""]);
    show(&["--tag","red","green,","b"]);
    // terminator consumed, next empty word restores options/positionals
    show(&["--tag","red",";",""]);
    show(&["--tag=red",";",""]);
    show(&["--label","red",";",""]);
    show(&["-tred",";",""]);
    show(&["--tag","red,green",";",""]);
    show(&["--tag=red,green",";",""]);
    // terminator then -- : only src/dst (no dirs here, no options)
    show(&["--tag","red",";","--",""]);
    show(&["--tag","red",";","--","s"]);
    // terminator typed itself at cursor (no trailing space)
    show(&["--tag","red",";"]);
    // errors
    show(&["--tag=red,",";",""]);
    show(&["--tag","red,",";",""]);
    show(&["--tag","red",";",";",""]);
    show(&["--tag","red",";x",""]);
    show(&["--tag","red","x;",""]);
    show(&["--tag=red;",""]);
    show(&["--tag=;x",""]);
    show(&["--tag=red;"]);
    show(&["--tag=;"]);
    show(&["--tag",";",""]);
    show(&["--tag=red,green,blue,",""]);
    show(&["--tag=red,green,blue,extra",""]);
    // three used
    show(&["--tag","red,green,blue",""]);
    show(&["--tag=red,green,blue",""]);
}
