use clap::{Arg, Command};
use clap_complete::engine::complete;
use std::ffi::OsString;
fn cv(c: &mut Command, words: &[&str]) -> String {
    let mut args = vec![OsString::from("do")];
    args.extend(words.iter().map(|s| OsString::from(*s)));
    match complete(c, args, words.len(), None) {
        Ok(cs) => cs.iter().map(|c| c.get_value().to_string_lossy().to_string()).collect::<Vec<_>>().join(","),
        Err(e) => format!("ERR:{}", e),
    }
}
// free-form num_args(1..) terminator (existing aot fixture shape)
fn freecmd() -> Command {
    Command::new("do").arg(Arg::new("arguments").num_args(1..).value_terminator(";"))
}
// free-form delimited with terminator
fn delimcmd() -> Command {
    Command::new("do").arg(Arg::new("t").long("t").num_args(1..=3).value_delimiter(',').value_terminator(";")).arg(Arg::new("o"))
}
#[test]
fn probe() {
    println!("free --arg [TAB]: {}", cv(&mut freecmd(), &["--arg-not",""]));
    println!("free pos val ; [TAB]: {}", cv(&mut Command::new("do").arg(Arg::new("arguments").num_args(1..).value_terminator(";")), &["a",";",""]));
    println!("delim free a,;x [TAB]: {}", cv(&mut delimcmd(), &["--t","a,;x"]));
    println!("delim free a;b [TAB]: {}", cv(&mut delimcmd(), &["--t","a;b"]));
    println!("delim free a,; [TAB]: {}", cv(&mut delimcmd(), &["--t","a,;"]));
}
EOF
cd /tmp/termcheck && cargo test --test cur -- --nocapture 2>&1 | grep -E "free|delim"

