    Command::new("tag")
        .arg(Arg::new("tag").long("tag").visible_alias("label").short('t')
            .num_args(1..=3).value_parser(["red","green","blue"])
            .value_delimiter(',').value_terminator(";"))
        .arg(Arg::new("raw").long("raw").action(ArgAction::SetTrue).conflicts_with("tag"))
        .arg(Arg::new("where").add(ArgValueCompleter::new(move |current: &OsStr| {
            let mut values = vec![CompletionCandidate::new("src"), CompletionCandidate::new("dst")];
            values.retain(|c| c.get_value().starts_with(&current.to_string_lossy()));
            values.extend(PathCompleter::dir().current_dir(dir.clone()).complete(current));
