/// Build the command from the terminator spec: a `--tag` option (visible
/// alias `--label` and short `-t`) with at most three comma-delimited values
/// chosen from a fixed set and the standalone terminator `;`; a valueless
/// `--raw` that conflicts with it; and a positional that accepts `src`/`dst`.
fn terminator_command() -> Command {
    Command::new("tag")
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .visible_alias("label")
                .short('t')
                .num_args(1..=3)
                .value_parser(["red", "green", "blue"])
                .value_delimiter(',')
                .value_terminator(";"),
        )
        .arg(
            clap::Arg::new("raw")
                .long("raw")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("tag"),
        )
        .arg(clap::Arg::new("r#where").value_parser(["src", "dst"]))
}

/// Like [`terminator_command`] but its positional also completes the
/// directories in `dir` in addition to `src`/`dst`.
fn terminator_command_with_dirs(dir: std::path::PathBuf) -> Command {
    use clap_complete::engine::ValueCompleter as _;
    terminator_command().arg(
        clap::Arg::new("r#where").add(ArgValueCompleter::new(move |current: &std::ffi::OsStr| {
            let prefix = current.to_string_lossy();
            let mut values: Vec<CompletionCandidate> = ["src", "dst"]
                .into_iter()
                .map(CompletionCandidate::new)
                .filter(|candidate| {
                    candidate
                        .get_value()
                        .to_string_lossy()
                        .starts_with(&*prefix)
                })
                .collect();
